#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
M="$ROOT/app/src/main/java/org/linote/mu300controller/MainActivity.java"
W="$ROOT/app/src/main/java/org/linote/mu300controller/WebInstallerClient.java"
pass=0
check() {
  local name="$1"; shift
  if "$@"; then echo "ok   $name"; pass=$((pass+1)); else echo "FAIL $name" >&2; exit 1; fi
}
check "step navigation excludes the separate about page" grep -Fq 'STEP_NAMES = {"设备连接", "系统与 ZIP", "目标传输", "计划与安装", "高级功能", "日志"}' "$M"
check "about entry shares the title row and has its own page" grep -Fq 'titleRow.addView(aboutButton' "$M" && grep -Fq 'aboutPage = column();' "$M" && grep -Fq 'toggleAboutPage()' "$M"
check "about page hides step navigation and returns to the previous step" grep -Fq 'tabScroller.setVisibility(View.GONE)' "$M" && grep -Fq 'showStep(returnStep)' "$M"
check "title has increased top spacing" grep -Fq 'header.setPadding(dp(18), dp(38), dp(18), dp(6))' "$M"
check "about footer links to Lino Notes and GitHub" grep -Fq 'friendLink("Lino 笔记", BLOG_URL, R.drawable.lino_logo)' "$M" && grep -Fq 'friendLink("GitHub 主页", GITHUB_URL, R.drawable.github_invertocat)' "$M" && grep -Fq 'https://www.linote.top/' "$M" && grep -Fq 'https://github.com/linote99' "$M"
check "friend links render their matching icon images" grep -Fq 'icon.setImageResource(iconRes)' "$M" && grep -Fq 'private LinearLayout friendLink(String label, String address, int iconRes)' "$M"
check "friend link image assets exist" bash -c '[[ -s "$1" && -s "$2" ]]' _ "$ROOT/app/src/main/res/drawable-nodpi/lino_logo.png" "$ROOT/app/src/main/res/drawable-nodpi/github_invertocat.png"
check "runtime log captures status and app log events" grep -Fq 'AppRuntimeLog.record("STATUS", s)' "$M" && grep -Fq 'AppRuntimeLog.record("APP", safe)' "$M"
check "runtime log persists uncaught Java exception stacks" grep -Fq 'Thread.setDefaultUncaughtExceptionHandler' "$ROOT/app/src/main/java/org/linote/mu300controller/AppRuntimeLog.java" && grep -Fq 'recordThrowable("FATAL"' "$ROOT/app/src/main/java/org/linote/mu300controller/AppRuntimeLog.java"
check "USB and ADB handshake stages are recorded" grep -Fq 'requestWait starting' "$ROOT/app/src/main/java/org/linote/mu300controller/UsbAdbTransport.java" && grep -Fq 'handshake: sending CNXN' "$ROOT/app/src/main/java/org/linote/mu300controller/AdbConnection.java"
check "USB scan refresh recomputes the connect button state" python3 -c 'import pathlib,sys; s=pathlib.Path(sys.argv[1]).read_text(); m=s[s.index("private void refreshUsbList()"):s.index("private void requestOrConnect()")]; assert "deviceSpinner.setAdapter(adapter);" in m and "updateButtons();" in m' "$M"
check "entering a step refreshes current transfer selection and button state" python3 -c 'import pathlib,sys; s=pathlib.Path(sys.argv[1]).read_text(); m=s[s.index("private void showStep("):s.index("private void toggleAboutPage()")]; assert "renderSelection();" in m' "$M"
check "long ZIP transfer reports progress and target-side verification" grep -Fq 'client.take(zip,name,hash,new AdbConnection.Progress()' "$M" && grep -Fq 'ZIP 已上传，正在由目标端复核 SHA-256 和 manifest' "$M" && grep -Fq 'conn.push(new File[]{inbox}, new String[]{STAGE + "/in/" + name}, new int[]{0644}, progress);' "$W" && grep -Fq 'if (onUploaded != null) onUploaded.run();' "$W"
check "step tabs and about navigation are disabled during operations" grep -Fq 'tab.setEnabled(!busy);' "$M" && grep -Fq 'aboutButton.setEnabled(!busy)' "$M"
check "hidden runtime-log export appears after five friend-title taps" grep -Fq 'exportRuntimeLogButton.setVisibility(View.GONE)' "$M" && grep -Fq 'friendTitleTaps >= 5' "$M" && grep -Fq 'Intent.ACTION_CREATE_DOCUMENT' "$M"
check "advanced feature hidden from default tabs, pending recovery remains visible" grep -Fq 'if (i == 4 && !advancedVisible()) continue;' "$M"
check "five taps within the reference 1.5-second window" grep -Fq 'now - lastTitleTap > 1500' "$M"
check "advanced mode is persisted" grep -Fq 'uiPrefs.edit().putBoolean("advanced", advancedOn).apply()' "$M"
check "title is the advanced-mode entry point" grep -Fq 'title.setOnClickListener(v -> titleTapped())' "$M"
check "userdata preflight requires a ready target with root and Magisk" grep -Fq 'target==null||!target.ready()' "$M"
check "ERASE confirmation requires both typed word and backup acknowledgment" grep -Fq 'backupAck.isChecked()&&"ERASE".contentEquals(input.getText())' "$M"
check "Lino-UFI APK-only backup scope is documented" grep -Fq '不含应用数据' "$M"
check "personal files require a separate backup" grep -Fq '个人文件还要单独备份' "$M"
check "post-format Lino-UFI / UFI-TOOLS ADB / Magisk / Shell sequence is documented" grep -Fq '用 Lino-UFI 安装 UFI-TOOLS → 在 UFI-TOOLS 中开启 ADB → 用 Lino-UFI 恢复 Magisk' "$M" && grep -Fq '重新给 Shell 授予 root' "$M"
check "companion app package is declared" grep -Fq 'top.linote.ufiinstaller' "$ROOT/app/src/main/AndroidManifest.xml"
check "Lino-UFI launch fallback URL is present" grep -Fq 'https://www.linote.top/posts/lino-ufi-tools-android/' "$M"
check "ZIP transfer and target-side hash verification require target root, not Magisk 26+" grep -Fq 'boolean transportConnected = adb != null && !adb.isClosed() && target != null && target.root;' "$M" && grep -Fq 'pushButton.setEnabled(!busy && transportConnected' "$M" && grep -Fq 'target == null || !target.root' "$M"
check "Magisk numeric version code is read with -V and compared correctly" grep -Fq "su -c 'magisk -V' 2>&1" "$M" && grep -Fq 'MagiskVersion.parseVersionCode(versionCodeLines)' "$M" && grep -Fq 'MagiskVersion.supportsInstaller(versionCode)' "$M"
check "read-only dry-run remains gated by a ready Magisk 26+ target" grep -Fq 'target==null||!target.ready()' "$M" && grep -Fq 'planButton.setEnabled(!busy && connected' "$M"
check "final INSTALL remains gated by Magisk 26+ and a verified plan" grep -Fq 'installButton.setEnabled(!busy && connected' "$M" && grep -Fq 'target==null||!target.ready()||installWasAttempted||s==null' "$M"
check "dry-run remains a separate gate before INSTALL" grep -Fq 'client.start("plan",name)' "$M" && grep -Fq '输入大写 INSTALL 才开始写入' "$M"
check "final INSTALL confirmation scrolls the full body, including its prompt and input" grep -Fq 'ScrollView confirmationScroll=new ScrollView(this)' "$M" && grep -Fq 'maxConfirmHeight' "$M" && grep -Fq 'box.addView(msg,params(-1,-2));' "$M" && grep -Fq 'box.addView(installPrompt,topParams(dp(6)))' "$M" && grep -Fq 'box.addView(input,topParams(dp(4)))' "$M" && grep -Fq 'confirmationScroll.addView(box,params(-1,-2));' "$M" && grep -Fq '.setView(confirmationScroll)' "$M"
check "reconnect follows the existing remote task, not a new install" grep -Fq 'new WebInstallerClient(this,conn).follow' "$M"
check "completed plan rc=3 does not block a new transfer; only running jobs do" grep -Fq 'RemoteJobState.blocksTransfer(kind,state,rc)' "$M" && grep -Fq 'return "running".equals(state);' "$ROOT/app/src/main/java/org/linote/mu300controller/RemoteJobState.java" && ! grep -Fq '"done".equals(state)&&rc==3' "$M"
check "target-file scan is in the usage page and only touches the app stage" grep -Fq '检测并清理目标端暂存文件' "$M" && grep -Fq 'TargetStageCleanup.inspectCommand()' "$M" && grep -Fq '/data/local/tmp/mu300-web' "$M" && grep -Fq '/data/adb/mu300-web' "$M"
check "target cleanup checks job state, symlinks and scanned file sizes" grep -Fq 'requireIdleHelperJob(client.status(false))' "$M" && grep -Fq 'TargetStageCleanup.deleteCommand(inventory)' "$M" && grep -Fq 'MU300-OTG-CLEAN|DONE' "$ROOT/app/src/main/java/org/linote/mu300controller/TargetStageCleanup.java"
check "target cleanup re-stages verified helpers before later operations" grep -Fq 'ensureHelperStaged(conn)' "$M" && grep -Fq 'client.stage();' "$M"
check "local cleanup entry is above the friend links" python3 -c 'import pathlib,sys; s=pathlib.Path(sys.argv[1]).read_text(); assert s.index("打开「清理本机占用」") < s.index("addFriendsFooter();")' "$M"
check "local cleanup preserves incomplete records and ADB keys" grep -Fq '"installed".equals(j.optString("state", ""))' "$ROOT/app/src/main/java/org/linote/mu300controller/CleanupActivity.java" && grep -Fq 'adbkey / adbkey.pub' "$ROOT/app/src/main/java/org/linote/mu300controller/CleanupActivity.java"
check "completed recovery records require verified ZIP export before deletion" grep -Fq 'if (backups && !exportVerified)' "$ROOT/app/src/main/java/org/linote/mu300controller/CleanupActivity.java" && grep -Fq 'verifyZip(uri)' "$ROOT/app/src/main/java/org/linote/mu300controller/CleanupActivity.java" && grep -Fq 'recordMatchesExport(record)' "$ROOT/app/src/main/java/org/linote/mu300controller/CleanupActivity.java"
check "local cleanup Activity is internal-only" grep -Fq 'android:name="org.linote.mu300controller.CleanupActivity" android:exported="false"' "$ROOT/app/src/main/AndroidManifest.xml"
echo "ui check: $pass passed"
